<section class="container py-4"><div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-4"><div><h1 class="h2 fw-bold">Lịch hẹn của tôi</h1><p class="text-secondary mb-0">Theo dõi các yêu cầu đặt lịch và lịch đã xác nhận.</p></div><a class="btn btn-primary" href="<?= e(url('patient.book')) ?>">+ Đặt lịch mới</a></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Mã lịch</th><th>Dịch vụ</th><th>Bác sĩ</th><th>Ngày</th><th>Thời gian</th><th>Trạng thái</th><th></th></tr></thead><tbody>
<?php foreach ($appointments as $a): ?><tr><td>#<?= (int)$a['MaLH'] ?></td><td><?= e($a['TenDV']) ?></td><td><?= e($a['TenBacSi']) ?></td><td><?= e($a['NgayKham']) ?></td><td><?= e(substr($a['GioBatDau'],0,5)) ?>–<?= e(substr($a['GioKetThuc'],0,5)) ?></td><td><?= status_badge($a['TrangThai']) ?></td><td><?php if (in_array($a['TrangThai'], ['CHO_XAC_NHAN','DA_XAC_NHAN'], true) && $a['NgayKham'] >= date('Y-m-d')): ?><form method="post" action="<?= e(url('patient.cancel')) ?>" onsubmit="return confirm('Bạn chắc chắn muốn hủy lịch hẹn?')"><?= csrf_field() ?><input type="hidden" name="MaLH" value="<?= (int)$a['MaLH'] ?>"><button class="btn btn-sm btn-outline-danger">Hủy</button></form><?php endif; ?></td></tr><?php endforeach; ?>
